content.text:
{
  "primary_meaning": "Godly wisdom or spiritual discernment expressed in prudent, obedient living that fears the Lord and builds on His word",
  "primary_basis": [
    "Proverbs 1:7",
    "Proverbs 9:10",
    "Matthew 7:24-27",
    "Matthew 25:1-13",
    "James 3:13-17",
    "1 Corinthians 1:18-31"
  ],
  "alternatives": [
    {
      "meaning": "Christ Himself as the wisdom of God",
      "basis": [
        "1 Corinthians 1:24",
        "1 Corinthians 1:30",
        "Colossians 2:3"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Worldly or human wisdom that is folly before God",
      "basis": [
        "1 Corinthians 1:20-25",
        "1 Corinthians 3:19"
      ],
      "prominence": "common"
    },
    {
      "meaning": "The Magi (wise men) as Gentile seekers who recognize and worship Christ",
      "basis": [
        "Matthew 2:1-12"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Practical shrewdness or cunning in dealing with a hostile world",
      "basis": [
        "Matthew 10:16"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "medium",
  "notes": "“Wise” functions more as a recurring ethical/spiritual attribute than as a concrete object-symbol (e.g., lamb, dove). Across wisdom literature and the Gospels it is consistently tied to fear of the Lord, readiness, and obedience; the main variations are contrastive (godly vs. worldly) or titular (Magi)."
}
